import pandas as pd

df = pd.read_csv('dataset/deletion_requests.csv')

na_cases = []
for idx, row in df.iterrows():
    txt = row['request_text'].lower()
    # Check if request asks NOT to delete or only asks for access/correction/export/update
    is_na = False
    if "leave the account" in txt or "keep the account" in txt or "continue using" in txt or "without removing" in txt:
        is_na = True
    elif "download my account information" in txt or "copy of last year's invoices" in txt:
        is_na = True
    elif "replace it with the new one and leave" in txt or "correct it without removing" in txt:
        is_na = True
    elif "marketing opt-out" in txt or "unsubscribe from" in txt:
        is_na = True

    if is_na:
        na_cases.append((row['case_id'], row['email'], row['request_text']))

print(f"Total definitely NOT_APPLICABLE cases: {len(na_cases)}")
for cid, em, txt in na_cases:
    print(f"{cid} | {em} | {txt}")

import pandas as pd

df = pd.read_csv('dataset/deletion_requests.csv')

non_english = []
for idx, row in df.iterrows():
    txt = row['request_text']
    # Check if text contains non-ascii characters or common foreign words
    is_foreign = any(ord(c) > 127 for c in txt) or any(w in txt.lower() for w in ['solicito', 'je demande', 'bitte', 'deseo', 'vorrei'])
    if is_foreign:
        non_english.append((row['case_id'], row['email'], txt))

print(f"Total non-English requests: {len(non_english)}")
# Group by first 30 chars of text to see templates
templates = {}
for cid, em, txt in non_english:
    key = txt[:40]
    if key not in templates:
        templates[key] = []
    templates[key].append(cid)

for k, v in templates.items():
    print(f"Template '{k}': {len(v)} cases, e.g. {v[:3]}")

