import json
import os
import re
import pandas as pd

users = pd.read_csv('dataset/user_identities.csv')
audit = pd.read_csv('dataset/user_audit_log.csv')

# Build comprehensive user profile map: user_id -> set of identifiers (emails, phones, hashes, names)
user_map = {}
for idx, r in users.iterrows():
    uid = r['user_id']
    user_map[uid] = {
        'user_id': uid,
        'emails': {str(r['email']).lower()} if pd.notna(r['email']) else set(),
        'phones': {str(r['phone'])} if pd.notna(r['phone']) else set(),
        'hashes': {str(r['email_hash'])} if pd.notna(r['email_hash']) else set(),
        'names': {str(r['name'])} if pd.notna(r['name']) else set(),
    }

for idx, r in audit.iterrows():
    uid = r['user_id']
    if uid in user_map:
        field = r['field_name']
        for val in [r['old_value'], r['new_value']]:
            if pd.notna(val) and str(val).strip():
                if field == 'email':
                    user_map[uid]['emails'].add(str(val).lower())
                elif field == 'phone':
                    user_map[uid]['phones'].add(str(val))
                elif field == 'email_hash':
                    user_map[uid]['hashes'].add(str(val))
                elif field == 'name':
                    user_map[uid]['names'].add(str(val))

print(f"Total resolved users: {len(user_map)}")
print("Sample user user_12:", user_map['user_12'])

import pandas as pd

reqs = pd.read_csv('dataset/deletion_requests.csv')
users = pd.read_csv('dataset/user_identities.csv')
audit = pd.read_csv('dataset/user_audit_log.csv')

email_to_uid = {}
for idx, r in users.iterrows():
    email_to_uid[str(r['email']).lower()] = r['user_id']

for idx, r in audit.iterrows():
    if r['field_name'] == 'email':
        if pd.notna(r['old_value']):
            email_to_uid[str(r['old_value']).lower()] = r['user_id']
        if pd.notna(r['new_value']):
            email_to_uid[str(r['new_value']).lower()] = r['user_id']

unresolved = []
resolved = 0
for idx, r in reqs.iterrows():
    em = str(r['email']).lower()
    if em in email_to_uid:
        resolved += 1
    else:
        unresolved.append((r['case_id'], r['email']))

print(f"Total requests: {len(reqs)}")
print(f"Resolved by email: {resolved}")
print(f"Unresolved: {len(unresolved)}")
if unresolved:
    print("Unresolved cases:", unresolved[:10])

import json
import pandas as pd

sample_out = pd.read_csv('dataset/sample_output.csv')
sample_req = pd.read_csv('dataset/sample_deletion_requests.csv')
activity = pd.read_csv('dataset/system_activity.csv')
users = pd.read_csv('dataset/user_identities.csv')
audit = pd.read_csv('dataset/user_audit_log.csv')

# Build mapping of email -> user_id
email_to_uid = {}
for idx, r in users.iterrows():
    email_to_uid[str(r['email']).lower()] = r['user_id']
for idx, r in audit.iterrows():
    if r['field_name'] == 'email':
        if pd.notna(r['old_value']):
            email_to_uid[str(r['old_value']).lower()] = r['user_id']
        if pd.notna(r['new_value']):
            email_to_uid[str(r['new_value']).lower()] = r['user_id']

for idx, row in sample_out.head(15).iterrows():
    cid = row['case_id']
    req = sample_req[sample_req['case_id'] == cid].iloc[0]
    uid = email_to_uid.get(str(req.email).lower())
    steps = json.loads(row['steps_json'])
    res_list = [s['resource_id'] for s in steps]
    # Check if resource is in system_activity
    in_act = {}
    for res in set(res_list):
        m = activity[activity['resource_id'] == res]
        if not m.empty:
            in_act[res] = m['details'].iloc[0]
    print(f"{cid} | user={uid} | steps_resources={res_list}")
    for res, det in in_act.items():
        print(f"   activity match for {res}: {det[:90]}")

