                for k in ['customer_reference', 'requester_email', 'requester_phone']:
                    if item.get(k): idents.add(str(item[k]).lower())
                observations.append({
                    'evidence_id': fid, 'captured_at': cap_dt, 'system_id': 'support_platform',
                    'resource_id': rid, 'category': 'SUPPORT_MESSAGE', 'state': st, 'identifiers': idents
                })

print(f"Total observations after service_resource_export: {len(observations)}")

