                    elif rid.startswith('export_'): sys_id, cat = 'export_service', 'USER_EXPORT'
                    elif rid.startswith('data_flow_'): sys_id, cat = 'integration_service', 'DATA_FLOW'
                    elif rid.startswith('backup_'): sys_id, cat = 'backup_service', 'BACKUP_ARCHIVE'
                    elif rid.startswith('audit_record_'): sys_id, cat = 'security_service', 'SECURITY_AUDIT_LOG'
                    elif rid.startswith('tombstone_'): sys_id, cat = 'identity_service', 'ACCOUNT_TOMBSTONE'
                    elif rid.startswith('marketing_'): sys_id, cat = 'marketing_platform', 'MARKETING_PROFILE'

                    st = 'PRESENT'
