import json
import pandas as pd

sample_out = pd.read_csv('dataset/sample_output.csv')

allowed_ops = {
    'FINDING': ['REPORT_REMAINING_RECORD', 'REPORT_EXPOSED_PII', 'REPORT_ACTIVE_DATA_FLOW', 'REPORT_RESTORE_RISK'],
    'REMEDIATION': ['DISABLE_DATA_FLOW', 'BLOCK_RESTORE', 'DELETE_RECORD', 'REDACT_RECORD', 'ANONYMIZE_RECORD'],
    'VERIFICATION': ['VERIFY_RECORD_ABSENT', 'VERIFY_RECORD_PRESENT', 'VERIFY_RECORD_REDACTED', 'VERIFY_RECORD_ANONYMIZED', 'VERIFY_DATA_FLOW_DISABLED', 'VERIFY_RESTORE_BLOCKED']
}

all_valid = True
for idx, r in sample_out.iterrows():
    cid = r['case_id']
    status = r['deletion_status']
    steps = json.loads(r['steps_json'])

    if status == 'NOT_APPLICABLE':
        if len(steps) != 0:
            print(f"Error in {cid}: NOT_APPLICABLE must have empty steps")
            all_valid = False
        continue

    phases = [s['phase'] for s in steps]

    if status == 'COMPLETE':
        if any(p != 'VERIFICATION' for p in phases):
            print(f"Error in {cid}: COMPLETE has non-verification steps")
            all_valid = False
        if any(not s.get('evidence_id') for s in steps):
            print(f"Error in {cid}: COMPLETE has missing evidence_id")
            all_valid = False

    elif status == 'INCOMPLETE':
        # Check phase ordering: FINDING -> REMEDIATION -> VERIFICATION
        seen = []
        for p in phases:
            if not seen or seen[-1] != p:
                seen.append(p)
        if seen != ['FINDING', 'REMEDIATION', 'VERIFICATION']:
            print(f"Error in {cid}: phase ordering is {seen}")
            all_valid = False

        # Check evidence_ids: findings MUST have evidence_id, rem and ver MUST NOT
        for s in steps:
            p = s['phase']
            ev = s.get('evidence_id', '')
            if p == 'FINDING' and not ev:
                print(f"Error in {cid}: FINDING missing evidence_id: {s}")
                all_valid = False
            elif p in ['REMEDIATION', 'VERIFICATION'] and ev != "":
                print(f"Error in {cid}: {p} has non-empty evidence_id: {s}")
                all_valid = False

print("Sample output rule verification complete. All valid?", all_valid)

import json
import pandas as pd

sample_out = pd.read_csv('dataset/sample_output.csv')

op_priority = {
    'FINDING': {
        'REPORT_REMAINING_RECORD': 1,
        'REPORT_EXPOSED_PII': 2,
        'REPORT_ACTIVE_DATA_FLOW': 3,
        'REPORT_RESTORE_RISK': 4
    },
    'REMEDIATION': {
        'DISABLE_DATA_FLOW': 1,
        'BLOCK_RESTORE': 2,
        'DELETE_RECORD': 3,
        'REDACT_RECORD': 4,
        'ANONYMIZE_RECORD': 5
    },
    'VERIFICATION': {
        'VERIFY_RECORD_ABSENT': 1,
        'VERIFY_RECORD_PRESENT': 2,
        'VERIFY_RECORD_REDACTED': 3,
        'VERIFY_RECORD_ANONYMIZED': 4,
        'VERIFY_DATA_FLOW_DISABLED': 5,
        'VERIFY_RESTORE_BLOCKED': 6
    }
}

all_sorted = True
for idx, r in sample_out.iterrows():
    cid = r['case_id']
    steps = json.loads(r['steps_json'])

    # Group by phase
    by_phase = {}
    for s in steps:
        p = s['phase']
        by_phase.setdefault(p, []).append(s)

    for p, p_steps in by_phase.items():
        # Check sort key
        def sort_key(st):
            return (op_priority[p][st['operation']], st['system_id'], st['resource_id'])

        sorted_steps = sorted(p_steps, key=sort_key)
        if p_steps != sorted_steps:
            print(f"Sort violation in {cid} phase {p}:")
            print("Actual:", [(s['operation'], s['system_id'], s['resource_id']) for s in p_steps])
            print("Expected:", [(s['operation'], s['system_id'], s['resource_id']) for s in sorted_steps])
            all_sorted = False

print("Sorting check complete. All sorted?", all_sorted)

