# Test on structured_service_events_eu_west_20260918.log
lines = open('dataset/evidence/logs/structured_service_events_eu_west_20260918.log', encoding='utf-8', errors='ignore').readlines()

traces = {}
for line in lines:
    line = line.strip()
    if not line: continue
    # extract json or key-value
    data = {}
    if '{' in line and '}' in line:
        try:
            json_str = line[line.find('{'):line.rfind('}')+1]
            data = json.loads(json_str)
        except Exception:
            pass
    tid = data.get('trace_id')
    if not tid:
        m_tid = re.search(r'trace_id[=:]\s*"?([a-zA-Z0-9_-]+)"?', line)
        if m_tid: tid = m_tid.group(1)

    if tid:
        t = traces.setdefault(tid, {'idents': set(), 'resources': set()})
        for k in ['subject_ref', 'customer_ref', 'user_id', 'email', 'lookup_key']:
            if data.get(k): t['idents'].add(str(data[k]).lower())
        rid = data.get('resource_id')
        if rid: t['resources'].add(rid)

print(f"Total traces found: {len(traces)}")
for tid, t in list(traces.items())[:10]:
    if t['idents'] and t['resources']:
        print(f"Trace {tid}: idents={t['idents']} -> resources={t['resources']}")

