import os
import pandas as pd

class IdentityResolver:
    def __init__(self, identities_path='dataset/user_identities.csv', audit_log_path='dataset/user_audit_log.csv'):
        self.identities_path = identities_path
        self.audit_log_path = audit_log_path
        self.user_profiles = {}
        self.identifier_to_uid = {}
        self._load()

    def _load(self):
        if not os.path.exists(self.identities_path):
            raise FileNotFoundError(f"Identities file not found: {self.identities_path}")

        users_df = pd.read_csv(self.identities_path)
        for _, r in users_df.iterrows():
            uid = str(r['user_id']).strip()
            em = str(r['email']).strip().lower() if pd.notna(r['email']) else None
            ph = str(r['phone']).strip() if pd.notna(r['phone']) else None
            eh = str(r['email_hash']).strip() if pd.notna(r['email_hash']) else None
            nm = str(r['name']).strip() if pd.notna(r['name']) else None

            self.user_profiles[uid] = {
                'user_id': uid,
                'canonical_email': em,
                'canonical_phone': ph,
                'canonical_name': nm,
                'emails': {em} if em else set(),
                'phones': {ph} if ph else set(),
                'hashes': {eh} if eh else set(),
                'names': {nm} if nm else set()
            }
            if em:
                self.identifier_to_uid[em] = uid
            if ph:
                self.identifier_to_uid[ph] = uid
            if eh:
                self.identifier_to_uid[eh] = uid
            self.identifier_to_uid[uid.lower()] = uid

        if os.path.exists(self.audit_log_path):
            audit_df = pd.read_csv(self.audit_log_path)
            for _, r in audit_df.iterrows():
                uid = str(r['user_id']).strip()
                if uid in self.user_profiles:
                    field = r['field_name']
                    for val in [r['old_value'], r['new_value']]:
                        if pd.notna(val) and str(val).strip():
                            sval = str(val).strip()
                            if field == 'email':
                                self.user_profiles[uid]['emails'].add(sval.lower())
                                self.identifier_to_uid[sval.lower()] = uid
                            elif field == 'phone':
                                self.user_profiles[uid]['phones'].add(sval)
                                self.identifier_to_uid[sval] = uid
                            elif field == 'email_hash':
                                self.user_profiles[uid]['hashes'].add(sval)
                                self.identifier_to_uid[sval] = uid
                            elif field == 'name':
                                self.user_profiles[uid]['names'].add(sval)

    def resolve(self, identifier):
        if not identifier:
            return None
        s = str(identifier).strip()
        low = s.lower()
        if low in self.identifier_to_uid:
            uid = self.identifier_to_uid[low]
            return self.user_profiles[uid]
        if s in self.identifier_to_uid:
            uid = self.identifier_to_uid[s]
            return self.user_profiles[uid]
        return None

    def get_all_identifiers(self, user_profile):
        if not user_profile:
            return set()
        uid = user_profile['user_id']
        res = {uid.lower()}
        res.update(user_profile['emails'])
        res.update(user_profile['phones'])
        res.update(user_profile['hashes'])
        return res

import os
import sys
import re
import json
import sqlite3
import pandas as pd
from datetime import datetime

def parse_iso(s):
    if not s or pd.isna(s):
        return datetime.min
    return datetime.fromisoformat(str(s).replace('Z', '+00:00'))

class EvidenceParser:
    def __init__(self, dataset_dir='dataset'):
        self.dataset_dir = dataset_dir
        self.evidence_files_path = os.path.join(dataset_dir, 'evidence_files.csv')
        self.activity_path = os.path.join(dataset_dir, 'system_activity.csv')
        self.ocr_cache_path = os.path.join(dataset_dir, 'evidence', 'images_ocr_cache.json')
        self.pdf_cache_path = os.path.join(dataset_dir, 'evidence', 'pdfs_cache.json')

        self.observations = []
        self.activity_records = []
        self.resource_to_activities = {}
        self._load()

    def _load(self):
        # 1. Load OCR & PDF caches if available
        ocr_cache = {}
        if os.path.exists(self.ocr_cache_path):
            with open(self.ocr_cache_path, 'r', encoding='utf-8') as fp:
                ocr_cache = json.load(fp)

        pdf_cache = {}
        if os.path.exists(self.pdf_cache_path):
            with open(self.pdf_cache_path, 'r', encoding='utf-8') as fp:
                pdf_cache = json.load(fp)

        # 2. Load system activity
        if os.path.exists(self.activity_path):
            act_df = pd.read_csv(self.activity_path)
            for _, r in act_df.iterrows():
                dt = parse_iso(r['event_time'])
                rid = str(r['resource_id']).strip() if pd.notna(r['resource_id']) else None
                rec = {
                    'activity_id': r['activity_id'],
                    'event_time': dt,
                    'event_type': r['event_type'],
                    'source_system': r['source_system'],
                    'target_system': r['target_system'],
                    'resource_id': rid,
                    'reported_result': r['reported_result'],
                    'details': str(r['details'])
                }
                self.activity_records.append(rec)
                if rid:
                    self.resource_to_activities.setdefault(rid, []).append(rec)

        # 3. Load evidence files
        if not os.path.exists(self.evidence_files_path):
            return

        evidence_df = pd.read_csv(self.evidence_files_path)
        for _, r in evidence_df.iterrows():
            fid = r['file_id']
            fpath = os.path.join(self.dataset_dir, r['file_path'])
            origin = r['origin']
            cap_dt = parse_iso(r['captured_at'])
            if not os.path.exists(fpath):
                continue
            ext = os.path.splitext(fpath)[1].lower()

            # A. Service resource export (JSON)
            if 'service_resource_export' in origin or 'service_resource_export' in fpath:
                with open(fpath, 'r', encoding='utf-8') as fp:
                    data = json.load(fp)
                    exports = data.get('service_exports', {})
                    # account_service
                    for item in exports.get('account_service', {}).get('profile_lookups', []):
                        rid = item.get('resource_id')
                        prof = item.get('profile')
                        status = item.get('status_code')
                        st = 'ABSENT' if (status == 404 or prof is None) else 'PRESENT'
                        idents = set()
                        if prof:
                            for k in ['customer_reference', 'email', 'phone', 'email_hash']:
                                if prof.get(k): idents.add(str(prof[k]).lower())
                        self.observations.append({
                            'evidence_id': fid, 'captured_at': cap_dt, 'system_id': 'account_service',
                            'resource_id': rid, 'category': 'USER_PROFILE', 'state': st, 'identifiers': idents
                        })
                    # analytics_platform
                    for item in exports.get('analytics_platform', {}).get('profiles', []):
                        rid = item.get('resource_id')
                        has_pii = any(item.get(k) for k in ['customer_reference', 'email', 'phone', 'email_hash'])
                        st = 'PRESENT' if has_pii else 'ANONYMIZED'
                        idents = set()
                        for k in ['customer_reference', 'email', 'phone', 'email_hash']:
                            if item.get(k): idents.add(str(item[k]).lower())
                        self.observations.append({
                            'evidence_id': fid, 'captured_at': cap_dt, 'system_id': 'analytics_platform',
                            'resource_id': rid, 'category': 'ANALYTICS_PROFILE', 'state': st, 'identifiers': idents
                        })
                    # backup_service
                    for item in exports.get('backup_service', {}).get('restore_entries', []):
                        rid = item.get('resource_id')
                        allowed = item.get('restore_allowed', False)
                        st = 'ACTIVE' if allowed else 'BLOCKED'
                        idents = set()
                        for k in ['customer_reference', 'customer_email']:
                            if item.get(k): idents.add(str(item[k]).lower())
                        self.observations.append({
                            'evidence_id': fid, 'captured_at': cap_dt, 'system_id': 'backup_service',
                            'resource_id': rid, 'category': 'BACKUP_ARCHIVE', 'state': st, 'identifiers': idents
                        })
                    # export_service
                    for item in exports.get('export_service', {}).get('exports', []):
                        rid = item.get('resource_id')
                        idents = set()
                        for k in ['customer_reference', 'owner_email', 'owner_phone']:
                            if item.get(k): idents.add(str(item[k]).lower())
