import os
import sys
import json
import pandas as pd
from datetime import datetime, timedelta

from identity_resolver import IdentityResolver
from evidence_parser import EvidenceParser, parse_iso

# Non-deletion phrases for NOT_APPLICABLE
NON_DELETION_PHRASES = [
    "leave the account", "not asking for deletion", "keep the account",
    "do not close", "without removing", "marketing lists only",
    "not a request to erase", "leave my profile", "continue using",
    "don't delete", "do not delete", "access request", "rectification",
    "correction only", "export only", "portable format"
]

def is_not_applicable_request(request_text):
    txt = str(request_text).lower()
    return any(p in txt for p in NON_DELETION_PHRASES)

# Priority index mappings according to official specification
OP_PRIORITY = {
    'FINDING': {
        'REPORT_REMAINING_RECORD': 1,
        'REPORT_EXPOSED_PII': 2,
        'REPORT_ACTIVE_DATA_FLOW': 3,
        'REPORT_RESTORE_RISK': 4
    },
    'REMEDIATION': {
        'DISABLE_DATA_FLOW': 1,
        'BLOCK_RESTORE': 2,
        'DELETE_RECORD': 3,
        'REDACT_RECORD': 4,
        'ANONYMIZE_RECORD': 5
    },
    'VERIFICATION': {
        'VERIFY_RECORD_ABSENT': 1,
        'VERIFY_RECORD_PRESENT': 2,
        'VERIFY_RECORD_REDACTED': 3,
        'VERIFY_RECORD_ANONYMIZED': 4,
        'VERIFY_DATA_FLOW_DISABLED': 5,
        'VERIFY_RESTORE_BLOCKED': 6
    }
}

class DeletionAuditor:
    def __init__(self, dataset_dir='dataset'):
        self.dataset_dir = dataset_dir
        self.resolver = IdentityResolver(
            os.path.join(dataset_dir, 'user_identities.csv'),
            os.path.join(dataset_dir, 'user_audit_log.csv')
        )
        self.parser = EvidenceParser(dataset_dir)

        # Load evidence manifest for timing lookups
        ev_csv = os.path.join(dataset_dir, 'evidence_files.csv')
        self.evidence_files = pd.read_csv(ev_csv).set_index('file_id') if os.path.exists(ev_csv) else None

    def audit_case(self, case_id, email, requested_at, reported_at, audit_at, request_text):
        # 1. Check for NOT_APPLICABLE intent
        if is_not_applicable_request(request_text):
            return {
                'case_id': case_id,
                'deletion_status': 'NOT_APPLICABLE',
                'steps_json': json.dumps([])
            }

        # 2. Resolve user identity
        prof = self.resolver.resolve(email)
        uid = prof['user_id'] if prof else None
        user_idents = self.resolver.get_all_identifiers(prof) if prof else {str(email).lower()}

        req_dt = parse_iso(requested_at)
        rep_dt = parse_iso(reported_at)
        aud_dt = parse_iso(audit_at)

        # 3. Collect observations matching user identifiers captured on or before audit_at
        user_obs = [
            o for o in self.parser.observations
            if (o['identifiers'] & user_idents) and o['captured_at'] <= aud_dt
        ]

        # Sort user observations by capture time descending (most recent first)
        user_obs.sort(key=lambda x: x['captured_at'], reverse=True)

        # 4. Collect deletion worker activities in the request window
        worker_acts = [
            a for a in self.parser.activity_records
            if a['source_system'] == 'deletion_worker' and 
               (req_dt - timedelta(minutes=15) <= a['event_time'] <= rep_dt + timedelta(hours=2))
        ]

        # 5. Discover user's resources
        resources = {}  # rid -> {'system_id': ..., 'category': ..., 'obs': ..., 'activity': ...}

        # From matched observations
        for o in user_obs:
            rid = o['resource_id']
            if not rid: continue
            if rid not in resources:
                resources[rid] = {
                    'system_id': o['system_id'],
                    'category': o['category'],
                    'obs': o,
                    'activity': None
                }

        # From deletion worker activities
        for a in worker_acts:
            rid = a['resource_id']
            if not rid: continue
            if rid not in resources:
                sys_id = a['target_system']
                cat = 'USER_PROFILE'
                if rid.startswith('search_'): cat = 'SEARCH_INDEX_ENTRY'
                elif rid.startswith('analytics_'): cat = 'ANALYTICS_PROFILE'
                elif rid.startswith('support_'): cat = 'SUPPORT_MESSAGE'
                elif rid.startswith('export_'): cat = 'USER_EXPORT'
                elif rid.startswith('data_flow_'): cat = 'DATA_FLOW'
                elif rid.startswith('backup_'): cat = 'BACKUP_ARCHIVE'
                elif rid.startswith('audit_record_'): cat = 'SECURITY_AUDIT_LOG'
                elif rid.startswith('tombstone_'): cat = 'ACCOUNT_TOMBSTONE'

                # Check if there is an observation in parser for this rid at or before aud_dt
                matching_obs = [
                    o for o in self.parser.observations
                    if o['resource_id'] == rid and o['captured_at'] <= aud_dt
                ]
                matching_obs.sort(key=lambda x: x['captured_at'], reverse=True)
                latest_o = matching_obs[0] if matching_obs else None

                resources[rid] = {
                    'system_id': sys_id,
                    'category': cat,
                    'obs': latest_o,
                    'activity': a
                }
            else:
                if not resources[rid]['activity']:
                    resources[rid]['activity'] = a

        # Check special direct mapping for account_001..account_010 if user_01..user_10
        if uid and uid.startswith('user_') and uid[5:].isdigit():
            u_num = int(uid[5:])
            if 1 <= u_num <= 10:
                expected_acc = f"account_{u_num:03d}"
                if expected_acc not in resources:
                    matching_obs = [
                        o for o in self.parser.observations
                        if o['resource_id'] == expected_acc and o['captured_at'] <= aud_dt
                    ]
                    matching_obs.sort(key=lambda x: x['captured_at'], reverse=True)
                    latest_o = matching_obs[0] if matching_obs else None
                    resources[expected_acc] = {
                        'system_id': 'account_service',
                        'category': 'USER_PROFILE',
                        'obs': latest_o,
                        'activity': None
                    }

        # 6. Determine primary evidence file for this case/round
        # Prefer the evidence file from the most relevant observations
        cited_ev_ids = [rinfo['obs']['evidence_id'] for rinfo in resources.values() if rinfo['obs']]
        primary_ev_id = cited_ev_ids[0] if cited_ev_ids else 'evidence_54'

        # 7. Generate findings, remediation, and verification steps
        findings = []
        remediations = []
        verifications = []

        for rid, rinfo in resources.items():
            sys_id = rinfo['system_id']
            cat = rinfo['category']
            obs = rinfo['obs']
            act = rinfo['activity']

            ev_id = obs['evidence_id'] if obs else primary_ev_id
            state = obs['state'] if obs else ('ABSENT' if act and act['reported_result'] == 'SUCCESS' else 'PRESENT')

            # Rule logic based on category
            if cat in ['USER_PROFILE', 'SECONDARY_IDENTIFIER', 'SEARCH_INDEX_ENTRY', 'USER_EXPORT', 'MARKETING_PROFILE']:
                # Action required: DELETE
                if state == 'PRESENT':
                    findings.append({
                        'phase': 'FINDING', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REPORT_REMAINING_RECORD', 'state': 'PRESENT', 'evidence_id': ev_id
                    })
                    remediations.append({
                        'phase': 'REMEDIATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'DELETE_RECORD', 'state': 'ABSENT', 'evidence_id': ''
                    })
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_ABSENT', 'state': 'ABSENT', 'evidence_id': ''
                    })
                else:
                    # Verified absent
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_ABSENT', 'state': 'ABSENT', 'evidence_id': ev_id
                    })

            elif cat in ['SUPPORT_MESSAGE', 'ACCOUNT_TOMBSTONE', 'EMAIL_DELIVERY_LOG']:
                # Action required: REDACT
                if state == 'PRESENT':
                    findings.append({
                        'phase': 'FINDING', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REPORT_EXPOSED_PII', 'state': 'PRESENT', 'evidence_id': ev_id
                    })
                    remediations.append({
                        'phase': 'REMEDIATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REDACT_RECORD', 'state': 'REDACTED', 'evidence_id': ''
                    })
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_REDACTED', 'state': 'REDACTED', 'evidence_id': ''
                    })
                else:
                    # Verified redacted
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_REDACTED', 'state': 'REDACTED', 'evidence_id': ev_id
                    })

            elif cat in ['ANALYTICS_PROFILE', 'PRODUCT_TELEMETRY']:
                # Action required: ANONYMIZE
                if state == 'PRESENT':
                    findings.append({
                        'phase': 'FINDING', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REPORT_EXPOSED_PII', 'state': 'PRESENT', 'evidence_id': ev_id
                    })
                    remediations.append({
                        'phase': 'REMEDIATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'ANONYMIZE_RECORD', 'state': 'ANONYMIZED', 'evidence_id': ''
                    })
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_ANONYMIZED', 'state': 'ANONYMIZED', 'evidence_id': ''
                    })
                else:
                    # Verified anonymized
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RECORD_ANONYMIZED', 'state': 'ANONYMIZED', 'evidence_id': ev_id
                    })

            elif cat == 'DATA_FLOW':
                # Action required: DISABLE
                if state == 'ACTIVE':
                    findings.append({
                        'phase': 'FINDING', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REPORT_ACTIVE_DATA_FLOW', 'state': 'ACTIVE', 'evidence_id': ev_id
                    })
                    remediations.append({
                        'phase': 'REMEDIATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'DISABLE_DATA_FLOW', 'state': 'DISABLED', 'evidence_id': ''
                    })
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_DATA_FLOW_DISABLED', 'state': 'DISABLED', 'evidence_id': ''
                    })
                else:
                    # Verified disabled
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_DATA_FLOW_DISABLED', 'state': 'DISABLED', 'evidence_id': ev_id
                    })

            elif cat == 'BACKUP_ARCHIVE':
                # Action required: BLOCK_RESTORE
                if state == 'ACTIVE':
                    findings.append({
                        'phase': 'FINDING', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'REPORT_RESTORE_RISK', 'state': 'ACTIVE', 'evidence_id': ev_id
                    })
                    remediations.append({
                        'phase': 'REMEDIATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'BLOCK_RESTORE', 'state': 'BLOCKED', 'evidence_id': ''
                    })
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RESTORE_BLOCKED', 'state': 'BLOCKED', 'evidence_id': ''
                    })
                else:
                    # Verified blocked
                    verifications.append({
                        'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                        'operation': 'VERIFY_RESTORE_BLOCKED', 'state': 'BLOCKED', 'evidence_id': ev_id
                    })

            elif cat in ['SECURITY_AUDIT_LOG', 'LEGAL_HOLD_RECORD']:
                # Action required: RETAIN
                verifications.append({
                    'phase': 'VERIFICATION', 'system_id': sys_id, 'resource_id': rid,
                    'operation': 'VERIFY_RECORD_PRESENT', 'state': 'PRESENT', 'evidence_id': ev_id
                })

        # 8. Determine overall status and structure
        is_incomplete = len(findings) > 0
        overall_status = 'INCOMPLETE' if is_incomplete else 'COMPLETE'

        # Sorting function
        def sort_steps(step_list, phase_name):
            return sorted(
                step_list,
                key=lambda s: (
                    OP_PRIORITY[phase_name].get(s['operation'], 99),
                    s['system_id'],
                    s['resource_id']
                )
            )

        final_steps = []
        if is_incomplete:
            # Phase 1: FINDINGS (citing evidence)
            sorted_f = sort_steps(findings, 'FINDING')
            final_steps.extend(sorted_f)

            # Phase 2: REMEDIATIONS (evidence_id = "")
            sorted_r = sort_steps(remediations, 'REMEDIATION')
            final_steps.extend(sorted_r)

            # Phase 3: POST-REMEDIATION VERIFICATIONS (evidence_id = "")
            sorted_v = sort_steps(verifications, 'VERIFICATION')
            for v in sorted_v:
                v['evidence_id'] = ''  # Must be empty in incomplete case per spec
            final_steps.extend(sorted_v)
        else:
            # COMPLETE: ONLY VERIFICATIONS (citing valid evidence)
            sorted_v = sort_steps(verifications, 'VERIFICATION')
            final_steps.extend(sorted_v)

        # Assign consecutive 1-based step numbers
        for idx, s in enumerate(final_steps, start=1):
            s['step_no'] = idx

        return {
            'case_id': case_id,
            'deletion_status': overall_status,
            'steps_json': json.dumps(final_steps)
        }

